<template><section><div class="page-heading"><div><h1>新增商品</h1><p>先建立商品与 SKU 事实；成本和毛利在商品详情页维护。</p></div></div><div class="panel"><el-form ref="formRef" :model="form" :rules="rules" label-width="92px"><el-form-item label="商品名称" prop="name"><el-input v-model.trim="form.name" /></el-form-item><el-form-item label="商品类目" prop="category"><el-input v-model.trim="form.category" /></el-form-item><el-form-item label="品牌"><el-input v-model.trim="form.brand" /></el-form-item><el-form-item label="商品描述"><el-input v-model="form.description" type="textarea" /></el-form-item><el-divider>SKU</el-divider><div v-for="(sku,index) in form.skus" :key="index" class="sku"><el-row :gutter="12"><el-col :xs="24" :sm="8"><el-input v-model.trim="sku.sku_name" placeholder="SKU 名称" /></el-col><el-col :xs="24" :sm="8"><el-input v-model.trim="sku.spec" placeholder="规格" /></el-col><el-col :xs="24" :sm="6"><el-input-number v-model="sku.price" :min="0" :precision="2" controls-position="right" aria-label="零售价" /><span class="unit">元（零售价可为 0，毛利待确认）</span></el-col><el-col :xs="24" :sm="2"><el-button link type="danger" :disabled="form.skus.length===1" @click="removeSku(index)">移除</el-button></el-col></el-row></div><el-button plain @click="addSku">添加 SKU</el-button><div class="actions"><el-button @click="router.push('/products')">取消</el-button><el-button type="primary" :loading="saving" @click="save">创建商品</el-button></div></el-form><el-alert v-if="error" class="alert" type="error" :title="error" :closable="false" /></div></section></template>
<script setup lang="ts">import { reactive, ref } from "vue"; import type { FormInstance } from "element-plus"; import { useRouter } from "vue-router"; import { useProductStore } from "../stores/product"; import { errorMessage } from "../api/client";
const router=useRouter(),store=useProductStore(),formRef=ref<FormInstance>(),saving=ref(false),error=ref(""); const form=reactive({name:"",category:"",brand:"",description:"",skus:[{sku_name:"",spec:"",price:0}]}); const rules={name:[{required:true,message:"请填写商品名称",trigger:"blur"}],category:[{required:true,message:"请填写商品类目",trigger:"blur"}]}; function addSku(){form.skus.push({sku_name:"",spec:"",price:0})}function removeSku(i:number){form.skus.splice(i,1)}async function save(){error.value="";const valid=await formRef.value?.validate().catch(()=>false);if(!valid)return;if(form.skus.some(s=>!s.sku_name)){error.value="每个 SKU 都需要名称";return;}saving.value=true;try{const product=await store.createProduct({...form,brand:form.brand||undefined,description:form.description||undefined});router.push(`/products/${product.id}`)}catch(e){error.value=errorMessage(e)}finally{saving.value=false}}</script><style scoped>.sku{padding:12px;background:#f8faf8;border-radius:6px;margin:8px 0}.unit{display:block;font-size:12px;color:#66766f;margin-top:4px}.actions{margin-top:24px;display:flex;justify-content:flex-end;gap:12px}.alert{margin-top:16px}</style>
